/* data/articles-philippines.js */
window.MORE=(window.MORE||[]).concat([
{id:"manila",t:"Manila",c:"Philippines",i:"🏙️",p:[["Founding","Miguel López de Legazpi founded Spanish Manila in 1571 beside the Pasig River, on the site of an existing Muslim settlement. The walled city of Intramuros became the center of colonial rule."],["Galleon trade","From 1565 to 1815, Manila galleons carried silver from Acapulco to Manila and Asian silk, porcelain and spices back, linking Asia with the Americas."],["Today","Metro Manila is home to more than 13 million people and is the country’s political, financial and cultural center."]],r:["ph","explor"]},
{id:"spanph",t:"Spanish Colonial Era",c:"Philippines",i:"⛪",p:[["Conquest","Spanish rule began after Legazpi’s arrival in Cebu in 1565 and lasted until 1898, about 333 years."],["Faith and society","Catholic missionaries converted much of the population, and today the Philippines is one of the largest Catholic countries in the world. Spanish also left its mark on names, food and law."],["Resistance","Revolts occurred throughout the period. The Dagohoy rebellion in Bohol, from 1744 to 1829, was one of the longest."]],r:["phrev","manila"]},
{id:"japocc",t:"The Japanese Occupation",c:"Philippines",i:"🎌",p:[["Invasion","Japan attacked the Philippines on 8 December 1941. Manila fell in January 1942, Bataan in April and the island fortress of Corregidor in May."],["Occupation","Prisoners of war endured the Bataan Death March, while Filipino guerrillas resisted throughout the occupation."],["Liberation","General MacArthur landed at Leyte on 20 October 1944. The Battle of Manila in February and March 1945 left much of the capital in ruins."]],r:["ww2","phrev"]},
{id:"edsa",t:"The EDSA People Power Revolution",c:"Philippines",i:"✊",p:[["Background","President Ferdinand Marcos declared martial law in 1972. The assassination of opposition leader Benigno Aquino Jr. in 1983 deepened opposition, and a disputed snap election followed in February 1986."],["Four days","From 22 to 25 February 1986, huge crowds gathered along Epifanio de los Santos Avenue (EDSA) to support a military revolt. Marcos left the country on 25 February and Corazon Aquino became president."],["Legacy","A new constitution followed in 1987, and the peaceful uprising became a model for later movements elsewhere."]],r:["ph","coldwar"]},
{id:"phlang",t:"Languages of the Philippines",c:"Philippines",i:"🗣️",p:[["Diversity","More than 170 languages are spoken across the islands, including Cebuano, Ilocano and Hiligaynon."],["National languages","Filipino, based mainly on Tagalog, and English are the official languages. English is widely used in government, education and business."],["Writing","Before Spanish arrival many peoples used scripts such as Baybayin. Today the Latin alphabet is used."]],r:["ph","madag"]},
{id:"phbio",t:"Philippine Biodiversity",c:"Philippines",i:"🦅",p:[["Megadiverse nation","The Philippines is one of the world’s megadiverse countries, with an unusually high share of species found nowhere else."],["Notable species","The Philippine eagle, the tarsier of Bohol and the tamaraw of Mindoro are among its best-known animals, and whale sharks gather off Donsol."],["Marine life","The country lies in the Coral Triangle. Tubbataha Reefs Natural Park, in the Sulu Sea, became a UNESCO World Heritage site in 1993."]],r:["reef","amazon"]},
{id:"banaue",t:"The Rice Terraces of the Cordillera",c:"Philippines",i:"🌾",p:[["Ifugao terraces","The Ifugao people carved rice terraces into the mountains of Luzon’s Cordillera. The Rice Terraces of the Philippine Cordilleras were inscribed as a UNESCO World Heritage site in 1995."],["Age","They are often said to be 2,000 years old, though some archaeological research suggests that many terraces are several centuries old."],["Water","Channels from forests on the mountain tops feed the terraces, which depend on careful community upkeep."]],r:["ph","andes"]},
{id:"phtyph",t:"Typhoons in the Philippines",c:"Philippines",i:"🌀",p:[["Typhoon belt","The Philippines lies along the busiest typhoon track in the western Pacific, and about 20 tropical cyclones enter its area of responsibility each year."],["Haiyan","Typhoon Haiyan, known locally as Yolanda, struck in November 2013 as one of the strongest landfalling storms ever recorded, and killed more than 6,000 people."],["Warnings","PAGASA, the national weather agency, issues forecasts and wind signal warnings, and gives storms local names."]],r:["climate","ph"]},
{id:"phfood",t:"Filipino Food",c:"Philippines",i:"🍲",p:[["Staples","Rice is the staple, served with dishes such as adobo, often called the national dish, and sinigang, a sour soup."],["Influences","Malay, Chinese, Spanish and American traditions all shaped the cuisine. Pancit came from Chinese settlers, and many festive dishes have Spanish names."],["Sweets","Halo-halo, a shaved-ice dessert, and ube, the purple yam, are popular treats."]],r:["ph","silk"]},
{id:"rizal",t:"José Rizal",c:"Philippines",i:"📖",p:[["Life","José Rizal was born on 19 June 1861 in Calamba, Laguna. He trained as an eye doctor and was also a writer, artist and linguist."],["Writings","His novels Noli Me Tangere (1887) and El Filibusterismo (1891) exposed abuses under Spanish rule and inspired reformers and revolutionaries."],["Death","Rizal was executed on 30 December 1896 at Bagumbayan, today’s Rizal Park in Manila, and is honored as the national hero."]],r:["phrev","print"]},
{id:"phpower",t:"The Philippine Power Industry",c:"Philippines",i:"💡",p:[["Restructuring","The Electric Power Industry Reform Act of 2001 split the industry into generation, transmission, distribution and supply, and paved the way for a wholesale market that began in 2006."],["Grids and operators","The country has three main grids, Luzon, Visayas and Mindanao. NGCP has run the transmission network since 2009 under a 25-year franchise, and IEMOP has operated the wholesale market since 2018."],["Energy mix","Coal supplies the largest share of generation, with geothermal, hydro, solar and wind making up much of the rest."]],r:["elec","renew"]}]);
