window.MORE=(window.MORE||[]).concat([
{id:"cebu",t:"Cebu",c:"Philippines",i:"🏝️",p:[["Magellan and Legazpi","Magellan reached Cebu in 1521 and was killed nearby at Mactan. Legazpi returned in 1565 and founded the settlement that became Cebu City, the oldest Spanish city in the Philippines."],["The Queen City of the South","Cebu City is a major port and business center in the Visayas. Magellan’s Cross and the Basilica del Santo Niño are among its best-known landmarks."],["Sinulog","Each January the Sinulog festival honors the Santo Niño with dances and parades that draw crowds from across the country."]],r:["explor","spanph"]},
{id:"mindanao",t:"Mindanao",c:"Philippines",i:"🌴",p:[["The southern island","Mindanao is the second largest island in the Philippines. Its highest point is Mount Apo, at 2,954 m, which is also the country’s highest peak."],["Cities and farming","Davao is the largest city on the island, and Mindanao grows much of the country’s bananas, pineapples and coconuts."],["Bangsamoro","The Bangsamoro Autonomous Region in Muslim Mindanao was established in 2019 after a peace process and a plebiscite."]],r:["ph","phbio"]},
{id:"palawan",t:"Palawan",c:"Philippines",i:"🏞️",p:[["Long island","Palawan is a long, narrow island province in the west of the Philippines, with hundreds of smaller islands around it."],["Underground river","The Puerto Princesa Underground River, a river that flows through a cave directly into the sea, is a UNESCO World Heritage site."],["Reefs and wildlife","Palawan has rich coral reefs, and its waters include the Tubbataha Reefs Natural Park. It is home to species such as the Palawan bearcat."]],r:["phbio","reef"]},
{id:"bohol",t:"Bohol",c:"Philippines",i:"🐒",p:[["Chocolate Hills","Bohol’s Chocolate Hills are more than 1,200 grass-covered, cone-shaped hills that turn brown in the dry season."],["Wildlife","The Philippine tarsier, a tiny nocturnal primate, lives on the island, and Panglao Island offers well-known diving."],["2013 earthquake","A magnitude 7.2 earthquake struck Bohol on 15 October 2013, damaging many centuries-old stone churches."]],r:["phbio","quake"]},
{id:"taal",t:"Taal Volcano",c:"Philippines",i:"🌋",p:[["A volcano in a lake","Taal Volcano, in Batangas, forms an island in Taal Lake, which fills a large ancient caldera."],["Eruptions","A deadly eruption in 1911 killed more than 1,000 people, and another in January 2020 forced hundreds of thousands to evacuate."],["Monitoring","The Philippine Institute of Volcanology and Seismology monitors Taal and issues alert levels for nearby communities."]],r:["volc","tect"]},
{id:"mayon",t:"Mayon Volcano",c:"Philippines",i:"🗻",p:[["A perfect cone","Mayon, in Albay province in Luzon, rises to about 2,460 m and is known for its almost perfectly symmetrical cone."],["Activity","It is one of the most active volcanoes in the country, and its 1814 eruption buried the town of Cagsawa."],["Legend","Its name is linked to the legend of Daragang Magayon, the beautiful maiden of Bicolano folklore."]],r:["volc","ph"]},
{id:"malolos",t:"The First Philippine Republic",c:"Philippines",i:"🏛️",p:[["Founding","The First Philippine Republic was inaugurated at Malolos, Bulacan, on 23 January 1899 with Emilio Aguinaldo as president."],["Constitution","The Malolos Constitution established a republic with a separation of powers and is often described as the first democratic constitution in Asia."],["End","The republic was overtaken by the Philippine–American War, and Aguinaldo was captured in March 1901."]],r:["phrev","rizal"]},
{id:"independence",t:"Philippine Independence",c:"Philippines",i:"🇵🇭",p:[["12 June 1898","Emilio Aguinaldo proclaimed independence at Kawit, Cavite, where the Philippine flag was raised and the national anthem was first played."],["1946","The United States recognized Philippine independence on 4 July 1946, after a transition period under the Commonwealth."],["Independence Day","The holiday was moved from 4 July to 12 June in 1962, to mark the 1898 proclamation."]],r:["phrev","malolos"]},
{id:"phfest",t:"Philippine Festivals",c:"Philippines",i:"🎉",p:[["Religious festivals","Ati-Atihan in Kalibo, Aklan, and Sinulog in Cebu honor the Santo Niño with drumming, dancing and costumes."],["Harvest and flowers","Pahiyas in Lucban, Quezon, decorates houses with rice and vegetables to give thanks for the harvest. Baguio’s Panagbenga is a flower festival held each February."],["Christmas","The Christmas season starts early, and the so-called ber months from September are known for lanterns, carols and Simbang Gabi dawn masses."]],r:["spanph","phfood"]},
{id:"phfolk",t:"Philippine Folklore",c:"Philippines",i:"🧚",p:[["Spirits and creatures","Folklore features creatures such as the aswang and the tikbalang, along with nature spirits tied to mountains, trees and rivers."],["Epics","The Ilocano epic Biag ni Lam-ang and the Hinilawod of Panay are among the many oral epics that peoples across the islands sang for generations."],["Tales","Ibong Adarna, a tale of an enchanted bird, is one of the best-known Filipino stories and has been adapted for stage and screen."]],r:["phlang","ph"]},
{id:"phecon",t:"The Philippine Economy",c:"Philippines",i:"📈",p:[["Services and industry","Services, including business process outsourcing, make up the largest share of the economy, followed by industry and agriculture."],["Remittances","Money sent home by overseas Filipino workers is worth several percent of national income and supports millions of households."],["Farming","The Philippines is one of the world’s largest producers of coconuts, and rice, bananas and sugar are also important crops."]],r:["ph","phpower"]},
{id:"baguio",t:"Baguio",c:"Philippines",i:"🌲",p:[["The Summer Capital","Baguio sits about 1,500 m up in the Cordillera mountains of Luzon, and its cool, pine-scented climate earned it the name Summer Capital of the Philippines."],["Founding","American colonial officials developed it as a hill station in the early 1900s, using a plan by the architect Daniel Burnham."],["Earthquake and rebirth","A magnitude 7.8 earthquake in July 1990 devastated the city, which has since rebuilt as a center of education, crafts and tourism."]],r:["banaue","ph"]}]);
