window.EXTRA=Object.assign(window.EXTRA||{},{
calc:[["Everyday calculus","Calculus helps engineers design bridges, doctors model how a drug spreads through the body and planners find the best shape or route for a task."]],
alg:[["Why it matters","Algebra underlies spreadsheets, computer programs and science formulas, from distance equals speed times time to Ohm’s law."]],
stats:[["Correlation and cause","Two things moving together do not prove that one causes the other, a trap known as confusing correlation with causation."]],
fib:[["Rabbits","Fibonacci posed a puzzle about breeding rabbits whose answer is the sequence, though real rabbits do not breed so neatly."]],
pi:[["Computing digits","Computers have calculated pi to trillions of digits, though about 40 digits are enough to measure the circumference of the observable universe to the width of a hydrogen atom."]],
infin:[["Zeno’s paradoxes","Zeno’s paradoxes, such as Achilles and the tortoise, challenged ancient thinkers with infinite sums that add up to a finite total."]],
hindu:[["Texts","The Upanishads explore the nature of the self, and the epics Ramayana and Mahabharata, which includes the Bhagavad Gita, are beloved across South and Southeast Asia."]],
islam:[["Learning","Between the 8th and 13th centuries scholars in cities such as Baghdad advanced medicine, astronomy and mathematics and translated Greek works."]],
christ:[["Arts and calendar","Christian themes shaped Western art, music and architecture, and the common Western calendar counts years from the traditional date of Jesus’s birth."]],
judaism:[["Hebrew","Hebrew, the language of the Torah, was revived as an everyday spoken language in the late 19th and 20th centuries."]],
stoic:[["Modern echoes","Stoic ideas influenced modern cognitive behavioral therapy and remain popular in self-help writing."]],
tao:[["Arts and practice","Taoist ideas influenced Chinese landscape painting, poetry, martial arts such as tai chi and traditional medicine."]],
elephant:[["Intelligence","Elephants use tools, mourn their dead and recognize themselves in mirrors, and communicate across long distances with low-frequency rumbles."]],
whale:[["Songs and journeys","Humpback whales sing complex songs and migrate thousands of kilometers between feeding and breeding waters."]],
insect:[["Social insects","Ants, bees and termites live in colonies with queens, workers and a division of labor, and honeybees communicate with a waggle dance."]],
shark:[["Senses","Sharks detect the tiny electric fields of prey using special organs called ampullae of Lorenzini."]],
mars:[["Water","Dry riverbeds and minerals show that liquid water once flowed on Mars, and ice remains at its poles and underground."]],
exoplanet:[["Types","Exoplanets include hot Jupiters, super-Earths and rocky worlds, and some orbit two stars at once."]],
comet:[["Meteor showers","When Earth passes through trails of comet dust, meteor showers such as the August Perseids result."]],
bigbang:[["Dark energy","In 1998 astronomers found that the expansion of the universe is speeding up, which is attributed to a mysterious dark energy."]]});

;
