window.EXTRA=Object.assign(window.EXTRA||{},{
shakes:[["Language","Shakespeare’s plays popularized many phrases still in use today, such as wild-goose chase and heart of gold."]],
homer:[["The Trojan Horse","The wooden horse that ended the Trojan War is told in later sources such as Virgil’s Aeneid, not in the Iliad itself."]],
novel:[["Serial novels","Dickens published many novels in monthly or weekly installments, which readers eagerly awaited."]],
impress:[["Post-Impressionists","Later artists such as Vincent van Gogh, Paul Cézanne and Paul Gauguin, called Post-Impressionists, built on the movement’s use of color and light."]],
musicw:[["Notation","Western music is written on a five-line staff, a system refined by medieval musicians, notably Guido of Arezzo around the year 1000."]],
cinema:[["Special effects","Georges Méliès’s A Trip to the Moon (1902) pioneered special effects with stop-motion and double exposure."]],
heart:[["Heart health","Heart disease is a leading cause of death worldwide, and exercise, a balanced diet and not smoking lower the risk."]],
lungs:[["Capacity","Healthy adult lungs can hold around 4 to 6 liters of air at full capacity."]],
digest:[["Enzymes","Saliva begins breaking down starch in the mouth, stomach enzymes digest proteins, and the pancreas adds more enzymes in the small intestine."]],
bones:[["Healing","A broken bone heals as new bone forms around the break, usually within weeks to months, and weight-bearing exercise helps keep bones dense."]],
sleep:[["Body clock","A body clock called the circadian rhythm, set largely by light, regulates sleepiness across roughly 24 hours."]],
nutri:[["Vitamins","Vitamin A helps vision, vitamin D helps the body absorb calcium for bones, and vitamin B12 is needed for nerves and blood."]],
davinci:[["Inventions","His notebooks sketch flying machines, a parachute, an armored vehicle and diving gear, few of which were built in his lifetime."]],
gothic:[["Light and glass","Stained-glass windows told biblical stories in colored light, and the rose windows at Chartres are among the finest."]],
jazz:[["Instruments","Typical jazz instruments include trumpet, saxophone, piano, double bass and drums, and swing bands of the 1930s popularized big-band jazz."]],
austen:[["Adaptations","Her novels have inspired many films and series, and Pride and Prejudice remains one of the most adapted English novels."]],
theatre:[["Masks and chorus","Actors wore masks, and a chorus sang and commented on the action in tragedies."]],
phlit:[["Contemporary writers","Writers such as Nick Joaquin, N. V. M. Gonzalez and Lualhati Bautista are widely read in the Philippines."]],
eye:[["Color blindness","Color blindness affects about 1 in 12 men and usually comes from a missing or faulty type of cone cell."]],
blood:[["Donation","One blood donation can help several patients, because donated blood is separated into red cells, plasma and platelets."]],
skin:[["Healing","When skin is cut, blood clots form a scab while new cells grow beneath it to close the wound."]],
vacc:[["Polio","Polio cases have fallen by more than 99% since 1988 thanks to vaccination campaigns."]],
exercise:[["Mood","Regular exercise is linked to better mood and lower stress, and even short walks can help."]],
ear:[["Popping ears","The Eustachian tube links the middle ear to the throat and opens when you swallow or yawn to equalize pressure, which is why ears pop on planes."]]});

