window.MORE=(window.MORE||[]).concat([
{id:"beatles",t:"The Beatles",c:"Music",i:"🎸",p:[["Formation","The Beatles formed in Liverpool around 1960. The classic lineup was John Lennon, Paul McCartney, George Harrison and Ringo Starr."],["Albums","Their album Sgt. Pepper’s Lonely Hearts Club Band, released in 1967, is often called one of the most influential records ever made."],["Legacy","The band split in 1970, after about ten years together, but their songs remain among the most recorded and played in history."]],r:["musicw","jazz"]},
{id:"hiphop",t:"Hip Hop",c:"Music",i:"🎤",p:[["Origins","Hip hop began in the Bronx, New York, in the 1970s. A party hosted by DJ Kool Herc in August 1973 is often cited as its birth."],["Four elements","The culture is built on four elements: rapping, or MCing, DJing, breakdancing and graffiti art."],["Global reach","It spread from New York to the whole world, and artists in hundreds of languages now rap about local life."]],r:["jazz","sound"]},
{id:"guitar",t:"The Guitar",c:"Music",i:"🎼",p:[["Origins","Plucked string instruments go back thousands of years. The modern Spanish guitar took shape in the 1800s."],["Electric guitar","Electric guitars appeared in the 1930s, and the Fender Stratocaster of 1954 became one of the most famous designs."],["Styles","The guitar is central to folk, blues, rock, flamenco and classical music, and many cultures have their own guitar-like instruments, from the Portuguese guitarra to the Hawaiian ukulele."]],r:["musicw","beatles"]},
{id:"olymp",t:"The Olympic Games",c:"Sports",i:"🏅",p:[["Ancient Games","The ancient Olympics were held at Olympia in Greece, and the first recorded Games took place in 776 BCE."],["Modern Games","Pierre de Coubertin helped revive them, and the first modern Olympics took place in Athens in 1896."],["A global movement","More than 200 national Olympic committees take part, and each Summer Games has more than 10,000 athletes. The Olympic motto, Citius, Altius, Fortius, is Latin for faster, higher, stronger."]],r:["greece","phsport"]},
{id:"soccer",t:"Football (Soccer)",c:"Sports",i:"⚽",p:[["Rules","Modern association football was codified in England in 1863 when the Football Association was formed."],["Global game","FIFA was founded in 1904, and the first World Cup was held in Uruguay in 1930."],["Reach","It is the most widely played and watched sport in the world, with millions of players in clubs and in the street."]],r:["phsport","bball"]},
{id:"bball",t:"Basketball",c:"Sports",i:"🏀",p:[["Invention","James Naismith invented basketball in Springfield, Massachusetts, in December 1891, using a peach basket and a set of thirteen rules."],["Growth","The National Basketball Association grew out of a league formed in 1946, and the sport spread worldwide through the Olympics."],["Around the world","Basketball is played in more than 200 countries, and it is the most popular sport in places such as the Philippines, Lithuania and Serbia."]],r:["phsport","olymp"]},
{id:"langevo",t:"How Languages Evolve",c:"Languages",i:"🗣️",p:[["Families","About 7,000 languages are spoken in the world, grouped into families. English, Spanish, Hindi and Russian belong to the Indo-European family."],["Change","Languages change as sounds shift and words are borrowed, which is why Old English is unreadable today without study."],["Austronesian","Malay, Malagasy, Tagalog and Hawaiian are Austronesian languages, a family that spread across the Pacific and Indian oceans."]],r:["phlang","madag"]},
{id:"alphabet",t:"The Alphabet",c:"Languages",i:"🔤",p:[["Phoenician roots","The first widely used alphabet came from the Phoenicians around 1050 BCE and had letters for consonants only."],["Greek and Latin","The Greeks added vowels, and the Romans adapted the Greek alphabet into the Latin alphabet used today."],["Other scripts","Cyrillic, Arabic, Devanagari and Hangul are other major writing systems, and many others, such as Ge’ez in Ethiopia and Baybayin in the Philippines, have long histories."]],r:["greece","phlang"]},
{id:"english",t:"The English Language",c:"Languages",i:"🇬🇧",p:[["Old and Middle English","English began as the Germanic language of Anglo-Saxon settlers. After the Norman Conquest of 1066, thousands of French words entered it."],["Modern English","The printing press and Shakespeare helped standardize spelling and vocabulary, and the Great Vowel Shift changed pronunciation between about 1400 and 1700."],["Global language","English is now used by well over a billion people as a first or second language and is a common language of science, business and the internet."]],r:["shakes","print"]},
{id:"taxes",t:"Taxes",c:"Economics and Society",i:"🧾",p:[["History","Ancient Egypt and Mesopotamia taxed grain and labor. Britain introduced income tax in 1799 to pay for war with France."],["Types","Governments collect income taxes, sales and value-added taxes and property taxes, usually through a national tax agency."],["Purpose","Taxes pay for roads, schools, health care and defense, and tax policy balances raising money with fairness and growth."]],r:["money","phecon"]},
{id:"labor",t:"Labor and Work",c:"Economics and Society",i:"👷",p:[["Industrial era","Factory work during the Industrial Revolution brought long hours and child labor, prompting workers to form unions."],["Reforms","New Zealand passed one of the first minimum wage laws in 1894, and the International Labour Organization was founded in 1919."],["Labor Day","International Workers’ Day is observed on 1 May in many countries, while the United States and Canada mark Labor Day in September."]],r:["indrev","inflation"]},
{id:"sugar",t:"Sugar",c:"Food and Agriculture",i:"🍬",p:[["Origins","Sugarcane was first domesticated in New Guinea around 8,000 years ago, and sugar crystallization was developed in India."],["Plantations","European demand drove sugar plantations in the Caribbean and Brazil, which relied on the Atlantic slave trade."],["Beet sugar and competition","Sugar is also made from sugar beet, a root crop grown in cooler climates. Beet sugar was developed in Europe in the early 1800s, when wars interrupted supplies of cane sugar, and today it provides about a fifth of the world’s sugar. Brazil and India are the largest producers of sugar from cane."]],r:["explor","phecon"]},
{id:"maize",t:"Maize (Corn)",c:"Food and Agriculture",i:"🌽",p:[["Origin","Maize was domesticated in southern Mexico about 9,000 years ago from a wild grass called teosinte."],["Staple","It was the foundation of Maya, Aztec and Inca diets, and the Maya myth of creation says that humans were made from maize."],["Today","Maize is used for food, animal feed and ethanol. It is the most widely grown grain in the world by weight, ahead of rice and wheat."]],r:["maya","rice"]}]);
